mapper.select:
SELECT EXISTS( SELECT 1 FROM tbl_dim_role WHERE delete_flag = 0 AND LOWER(role_name) = LOWER(#{roleName})
AND role_id <> #{excludeRoleId}
)

mapper.update:
UPDATE tbl_dim_role
SET delete_flag = 1,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE role_id = #{roleId}
  AND delete_flag = 0
